<script setup lang="ts">import{onMounted,ref}from'vue';import{CheckCircle2,XCircle,HardDrive,Cpu}from'lucide-vue-next';import{api}from'../api';import{PageHeader}from'../components/Common.vue';const settings=ref<any>(),env=ref<any>();onMounted(async()=>{[settings.value,env.value]=await Promise.all([api('/settings'),api('/environment')])});</script>
<template><PageHeader eyebrow="SYSTEM BASELINE" title="系统设置" description="当前实例的数据边界、并发策略与构建工具状态。"/><section class="settings-grid"><article class="setting-hero"><HardDrive/><span>安全数据根目录</span><strong>{{settings?.dataRoot}}</strong><p>数据库、密钥、工作区、版本、压缩包与日志在此目录下相互隔离。</p></article><article class="setting-card"><Cpu/><h3>运行策略</h3><dl><dt>最大并发发布</dt><dd>{{settings?.maxConcurrentDeployments}}</dd><dt>会话时长</dt><dd>{{settings?.sessionHours}} 小时</dd><dt>运行平台</dt><dd>{{settings?.platform}}</dd><dt>.NET Runtime</dt><dd>{{settings?.framework}}</dd></dl></article></section><h2 class="subhead">构建环境</h2><section class="tool-grid"><article v-for="(v,k) in env" :key="k"><component :is="v.available?CheckCircle2:XCircle" :class="v.available?'good':'bad-text'"/><div><strong>{{String(k).toUpperCase()}}</strong><small>{{v.version||'未发现'}}</small></div></article></section></template>
